-- Phase 1 schema (docs/ARCHITECTURE.md, Data model). Ids are UUID v7 generated by the app.
-- pgvector is deliberately not enabled in phase 1.
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE users (
    id            uuid PRIMARY KEY,
    email         citext NOT NULL UNIQUE,
    password_hash text, -- NULL until the invite is accepted, and after a password reset
    created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE sessions (
    token_hash bytea PRIMARY KEY, -- SHA-256 of the cookie token
    user_id    uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);

CREATE TABLE canvases (
    id           uuid PRIMARY KEY,
    user_id      uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    title        text NOT NULL,
    root_node_id uuid,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX canvases_user_id_updated_at_idx ON canvases (user_id, updated_at DESC);

CREATE TABLE nodes (
    id                 uuid PRIMARY KEY,
    canvas_id          uuid NOT NULL REFERENCES canvases ON DELETE CASCADE,
    type               text NOT NULL CHECK (type IN ('user_message', 'ai_message')),
    content            text NOT NULL DEFAULT '' CONSTRAINT nodes_content_length CHECK (char_length(content) <= 100000),
    status             text NOT NULL CHECK (status IN ('streaming', 'complete', 'error')),
    error_code         text,
    attempt            int NOT NULL DEFAULT 0,
    rev                int NOT NULL DEFAULT 0,
    owner_key          bigint,
    model              text,
    prompt_tokens      int,
    completion_tokens  int,
    cached_tokens      int,
    ctok               int,
    tok                jsonb,
    block_acc          int,
    is_checkpoint      boolean NOT NULL DEFAULT false,
    compaction_summary text,
    compaction_tokens  int,
    position_x         double precision NOT NULL,
    position_y         double precision NOT NULL,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),
    -- target of the edges' composite FKs; its leading column also serves as the canvas_id index
    CONSTRAINT nodes_canvas_id_id_key UNIQUE (canvas_id, id),
    CONSTRAINT nodes_summary_needs_checkpoint CHECK (compaction_summary IS NULL OR is_checkpoint)
);
CREATE INDEX nodes_streaming_owner_key_idx ON nodes (owner_key) WHERE status = 'streaming';

CREATE TABLE edges (
    id            uuid PRIMARY KEY,
    canvas_id     uuid NOT NULL,
    source_id     uuid NOT NULL,
    target_id     uuid NOT NULL,
    type          text NOT NULL CHECK (type IN ('reply', 'branch')),
    anchor        jsonb,
    doubt_type    text CHECK (doubt_type IN ('simpler', 'example', 'why', 'deeper', 'wrong', 'free')),
    merge_summary text,
    merge_ctok    int,
    merged_at     timestamptz,
    merged_rev    bigint,
    last_proposal text,
    collapsed     boolean NOT NULL DEFAULT false,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT edges_source_fkey FOREIGN KEY (canvas_id, source_id) REFERENCES nodes (canvas_id, id) ON DELETE CASCADE,
    CONSTRAINT edges_target_fkey FOREIGN KEY (canvas_id, target_id) REFERENCES nodes (canvas_id, id) ON DELETE CASCADE,
    CONSTRAINT edges_target_id_key UNIQUE (target_id),
    CONSTRAINT edges_branch_fields CHECK ((type = 'branch') = (anchor IS NOT NULL AND doubt_type IS NOT NULL)),
    CONSTRAINT edges_branch_only_state CHECK (type = 'branch' OR (merge_summary IS NULL AND NOT collapsed))
);
CREATE UNIQUE INDEX edges_one_reply_per_source ON edges (source_id) WHERE type = 'reply';
CREATE INDEX edges_source_id_idx ON edges (source_id);
CREATE INDEX edges_canvas_id_idx ON edges (canvas_id);

-- No FKs: cost records outlive account and canvas deletion.
CREATE TABLE llm_usage (
    id                bigserial PRIMARY KEY,
    user_id           uuid NOT NULL,
    node_id           uuid,
    kind              text NOT NULL CHECK (kind IN ('answer', 'compaction', 'merge_proposal')),
    model             text NOT NULL,
    owner_key         bigint NOT NULL,
    reserved_tokens   int NOT NULL,
    prompt_tokens     int,
    completion_tokens int,
    cached_tokens     int,
    estimated         boolean NOT NULL DEFAULT false,
    created_at        timestamptz NOT NULL DEFAULT now(),
    settled_at        timestamptz,
    CONSTRAINT llm_usage_settled_counts CHECK (settled_at IS NULL OR (prompt_tokens IS NOT NULL AND completion_tokens IS NOT NULL))
);
CREATE INDEX llm_usage_user_id_created_at_idx ON llm_usage (user_id, created_at);
CREATE INDEX llm_usage_unsettled_user_id_idx ON llm_usage (user_id) WHERE settled_at IS NULL;

-- No FK: restore runbook input.
CREATE TABLE tombstones (
    kind text NOT NULL CHECK (kind IN ('user_deleted', 'canvas_deleted', 'password_reset')),
    id   uuid NOT NULL,
    at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE invites (
    token_hash bytea PRIMARY KEY,
    user_id    uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    expires_at timestamptz NOT NULL,
    used_at    timestamptz
);

CREATE TABLE events (
    id         bigserial PRIMARY KEY,
    user_id    uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    canvas_id  uuid NOT NULL REFERENCES canvases ON DELETE CASCADE,
    kind       text NOT NULL CHECK (kind IN ('branch_created', 'merge_confirmed', 'merge_updated', 'back_to_main', 'collapse')),
    payload    jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX events_user_id_created_at_idx ON events (user_id, created_at);
